protected boolean enterPIPMode(){
  if (enteringPIPMode) {
    return true;
  }
  if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O && appPlayer != null && !startingFilePickerActivity && !startingSignInFlowActivity) {
    enteringPIPMode=true;
    PictureInPictureParams params=new PictureInPictureParams.Builder().build();
    enterPictureInPictureMode(params);
    return true;
  }
  return false;
}
